return {
    ["丑戏谢幕"] = "Занавес для шутов",
    ["丧钟回响"] = "",
    ["仲裁执行"] = "Исполнение Арбитража",
    ["仲裁烙印"] = "",
    ["先祖庇护"] = "Защита предков",
    ["冰焰吐息"] = "Дыхание ледяного пламени",
    ["匿形刺击"] = "Скрытный укол",
    ["变身成河豚，短暂延迟后爆炸，并向四周发射<Highlight>4</>个子弹，每个造成*d点伤害。变身过程中全程<Highlight>霸体</>。"] = "Превращается в рыбу-фугу, которая после небольшой задержки взрывается и выпускает во все стороны <Highlight>4</> снаряда, каждый из которых наносит *d ед. урона. На протяжении всего превращения действует <Highlight>Суперброня</>.",
    ["变身成河豚，短暂延迟后爆炸，并向四周发射多个子弹。变身过程中全程霸体"] = "Превращает в рыбу-фугу: после небольшой задержки происходит взрыв, выпускающий множество снарядов во все стороны. Во время превращения на всём протяжении действует Суперброня.",
    ["召唤“头狼”鲁珀连续发动三次爪击，每次爪击造成*d点伤害，并有50%的基础概率使目标僵直0.3秒。召唤的8秒内使自身buffdisc(*id)"] = "Призывает «Вожака стаи» Лупо для совершения трёх последовательных ударов когтями; каждый удар наносит *d ед. урона и с базовой вероятностью 50% оглушает цель на 0,3 сек. В течение 8 сек. призыва накладывает на себя buffdisc(*id).",
    ["召唤“头狼”鲁珀，攻击敌人使其僵直，并为自身附加攻击增益。"] = "Призывает «Вожака» Люпера, атакующего противников, накладывающего ошеломление и дающего вам прибавку к атаке.",
    ["召唤一号信徒·安西娅，为目标附加庇佑状态，持续6秒。庇佑期间目标受到致命伤害时，使其恢复15%最大生命值并消耗庇佑。庇佑未被消耗且时间结束时，目标恢复30%最大生命值。\n获得庇佑的玩家在<Highlight>25</>秒内无法再次获得庇佑。\n该技能有小队冷却时间<Highlight>30</>秒。"] = "Призывает Первого последователя, Антею, чтобы наложить на цель покровительство на 6 сек. Если цель получает смертельный урон под покровительством, она восстанавливает 15% макс. ОЗ, а покровительство расходуется. Если покровительство не израсходовано к концу действия, цель восстанавливает 30% макс. ОЗ.\nИгрок, получивший покровительство, не может получить его снова в течение <Highlight>25</> сек.\nУ этого навыка общий откат отряда <Highlight>30</> сек.",
    ["召唤一号信徒·安西娅，为目标附加庇佑，保护生命。"] = "Призывает Первого последователя, Антею, чтобы наложить на цель покровительство, защищающее жизнь.",
    ["召唤乌洛琉斯残影，向前方15米释放黑色湍流冲击，随后6秒内可以手动释放第二段白色湍流冲击，效果如下。\n黑色湍流：只对敌人有效，击退敌人的同时附带8秒黑色命运效果，每秒对敌人造成一定伤害，若敌人在此期间死亡，则原地产生一次爆炸对范围内敌人造成额外伤害。\n白色湍流：只对友方有效，瞬间回复一定生命值，并在未来8秒内提升移动速度和免伤效果。"] = "Вызывает остаточное изображение Уролиуса, выпускает черный турбулентный удар в 15 метрах вперед, а затем вручную выпускает второй белый турбулентный удар в течение 6 секунд. Эффект заключается в следующем. \n Черная турбулентность: действует только на врага. Он оттолкнет врага и будет иметь эффект черной судьбы на 8 секунд. Это будет наносить определенное количество урона противнику каждую секунду. Если враг умрет в этот период, на месте произойдет взрыв, который нанесет дополнительный урон врагам в радиусе действия. \nБелая турбулентность: эффективна только для дружественных групп, мгновенно восстанавливает определенное количество здоровья, увеличивает скорость передвижения и эффект без урона в течение следующих 8 секунд.",
    ["召唤乌洛琉斯残影，向前方释放黑色湍流冲击，随后6秒内可以手动释放第二段白色湍流冲击。\n黑色湍流：只对敌人有效，击退敌人同时附带持续伤害，若敌人在此期间死亡，则原地产生一次爆炸伤害。\n白色湍流：只对友方有效，瞬间回复一定生命值，并在未来8秒内提升移动速度和免伤效果。"] = "Призывает остаточный образ Уробороса, который выпускает вперед черный бурный поток, после чего в течение 6 секунд можно вручную выпустить второй, белый бурный поток.\nЧерный поток: действует только на врагов, отбрасывая их и нанося периодический урон; если враг погибает во время действия эффекта, на его месте происходит взрыв с нанесением урона.\nБелый поток: действует только на союзников, мгновенно восстанавливая определенное количество здоровья и повышая скорость передвижения и снижение урона на следующие 8 секунд.",
    ["召唤先祖铠甲为自己添加法阵，范围内友方获得增强。"] = "Призывает доспехи предков, чтобы добавить к вам магический круг, а союзники в радиусе действия будут усилены.",
    ["召唤先祖铠甲，在自己脚下召唤一个半径30米，持续<Highlight>10</>秒的法阵，使得范围内的同小队友方buffdisc(*id)。\n先祖庇护：自己每主动治疗友方3次，在自己脚下生成先祖庇护，半径5米，持续2.5秒，每4秒最多触发一次，使得范围内的友方buffdisc(*id)。\n法阵和先祖庇护不能同时存在且同时至多存在一个先祖庇护。\n该技能有小队冷却时间<Highlight>30</>秒。"] = "Призывает доспех предков, создавая под ногами магический круг радиусом 30 м на <Highlight>10</> сек., который наделяет союзников по отряду в зоне действия эффектом buffdisc(*id).\nЗащита предков: каждые 3 активных исцеления союзников создают под ногами область Защиты предков радиусом 5 м на 2,5 сек. (срабатывает не чаще раза в 4 сек.), наделяя союзников в области эффектом buffdisc(*id).\nМагический круг и Защита предков не могут действовать одновременно, и на поле боя может присутствовать не более одной Защиты предков.\nНавык имеет общекомандное время перезарядки <Highlight>30</> сек.",
    ["召唤剥面人，发射弹射子弹，对友方和敌方造成不同的效果。"] = "Призывает Сдирателя Лиц, выпускающего рикошетящие пули, которые по-разному воздействуют на союзников и врагов.",
    ["召唤剥面人，对范围内敌人发射弹射子弹，子弹会在附近的友方和敌方之间弹射，命中敌方时造成bulletdisc(*id)伤害，命中友方时buffdisc(*id)。"] = "Призывает Сдирателя Лиц, который выпускает в находящихся в зоне действия врагов рикошетящие пули. Пули отскакивают между ближайшими союзниками и врагами, нанося bulletdisc(*id) ед. урона при попадании по врагам и накладывая buffdisc(*id) при попадании по союзникам.",
    ["召唤子爵夫人攻击目标，对目标造成bulletdisc(*id)伤害并添加幽魂附身10秒，附身期间增加5%自身对目标的伤害。\n若目标为玩家：若10秒内该目标死亡，则幽魂会另外随机寻找15米内一个敌方玩家造成bulletdisc(*id)伤害并附身，最多额外附身1次。\n若目标为怪物：幽魂会对怪物额外造成基础伤害30%的伤害，并使附身时间延长30%。"] = "Призывает виконтессу для атаки цели: наносит bulletdisc(*id) ед. урона и накладывает вселение призрака на 10 сек., во время которого наносимый вами урон по цели повышается на 5%.\nЕсли цель — игрок: если эта цель погибает в течение 10 сек., призрак выбирает другого случайного вражеского игрока в радиусе 15 м, наносит ему bulletdisc(*id) ед. урона и вселяется в него (не более 1 дополнительного вселения).\nЕсли цель — монстр: призрак наносит монстру дополнительный урон в размере 30% от базового и продлевает время вселения на 30%.",
    ["召唤子爵夫人攻击目标，对目标造成一次伤害并添加幽魂附身，期间自身对目标伤害提升。\n若目标为玩家：若一段时间内该目标死亡则幽魂会寻找附近另外一个敌方玩家附身。\n若目标为怪物：幽魂会对怪物额外造成伤害并延长附身时间。"] = "Призывает виконтессу для атаки цели: наносит урон и накладывает вселение призрака, во время которого наносимый вами урон по цели повышается.\nЕсли цель — игрок: если цель погибает в течение некоторого времени, призрак вселяется в другого находящегося поблизости вражеского игрока.\nЕсли цель — монстр: призрак наносит монстру дополнительный урон и продлевает время вселения.",
    ["召唤异化猎犬，以锁定目标为基准点进行跃击，造成*d点伤害并击飞。"] = "Призывает Искажённую Гончую, совершающую прыжок на захваченную цель, нанося *d ед. урона и подбрасывая её.",
    ["召唤异化猎犬，向附近目标进行跃击造成高额伤害并击飞。"] = "Призывает Искажённую Гончую, совершающую прыжок на ближайшие цели, нанося высокий урон и подбрасывая их.",
    ["召唤星之虫幻化为的秘偶向前方直线区域随机释放火焰吐息或者冰霜吐息。\n火焰吐息：对路径上的敌方造成*d点伤害，并对敌方玩家附加*d秒<HighLight>68%</>的<HyperLink stylename=\"M_Link\" u=\"10\">重伤</>。\n冰霜吐息：对路径上的敌方造成*d点伤害，并有70%的基础概率使敌方buffdisc(*id)，持续*f秒。"] = "Призывает марионетку, созданную из Звёздного червя, которая случайным образом выпускает перед собой по прямой линии дыхание пламени или морозное дыхание.\nДыхание пламени: наносит *d ед. урона врагам на пути и накладывает на вражеских игроков эффект <HyperLink stylename=\"M_Link\" u=\"10\">Тяжёлое ранение</> на *d сек. с эффективностью <HighLight>68%</>.\nМорозное дыхание: наносит *d ед. урона врагам на пути и с базовой вероятностью 70% накладывает на противника buffdisc(*id) на *f сек.",
    ["召唤星之虫幻化为的秘偶释放回旋斩击，对路径上的敌方造成伤害并<HighLight>击退</>。"] = "Призывает марионетку, созданную из Звёздного червя, для проведения вихревого рассекающего удара, наносящего урон врагам на пути и вызывающего <HighLight>Отбрасывание</>.",
    ["召唤星之虫幻化为的秘偶释放回旋斩击，对路径上的敌方造成伤害并击退。"] = "Призывает марионетку, созданную из Звёздного червя, для кругового рубящего удара, наносящего урон врагам на пути и отбрасывающего их.",
    ["召唤星之虫幻化为的秘偶释放奇迹牌雨，对目标范围内敌方造成伤害，同时眩晕范围中心的敌方。"] = "Призывает марионетку, созданную из Звёздного червя, обрушивающую Дождь Чудесных Карт: наносит урон врагам в целевой области и оглушает врагов в её центре.",
    ["召唤星之虫幻化为的秘偶释放日冕裁决，挥出剑气对前方范围内的敌人造成*d点伤害，随后推出剑气对路径上的敌人造成*d点伤害。"] = "Призывает марионетку, созданную из Звёздного червя, для применения «Приговора Солнечной Короны»: взмах клинка выпускает волну энергии, наносящую *d ед. урона врагам перед собой, после чего выпад волной наносит *d ед. урона врагам на своём пути.",
    ["召唤星之虫幻化为的秘偶释放日冕裁决，挥出剑气对前方范围内的敌人造成伤害，随后推出剑气对路径上的敌人造成伤害。"] = "Призывает марионетку, созданную из Звёздного червя, для применения «Приговора Солнечной Короны»: взмах клинка выпускает волну энергии, наносящую урон врагам перед собой, а последующий выпад волной наносит урон врагам на своём пути.",
    ["召唤星之虫幻化为的秘偶释放日暮飓风，持续打击秘偶周身敌方造成伤害和减速。"] = "Призывает марионетку, созданную из Звёздного червя, для вызова «Сумеречного Урагана», непрерывно поражающего врагов вокруг марионетки, нанося урон и замедляя их.",
    ["召唤星之虫幻化为的秘偶释放星云斩击，对目标4米范围内敌方造成*d点伤害。"] = "Призывает марионетку, созданную из Звёздного червя, для нанесения «Туманного Разреза», наносящего *d ед. урона врагам в радиусе 4 метров от цели.",
    ["召唤星之虫幻化为的秘偶释放星云斩击，对目标范围内敌方造成伤害。"] = "Призывает марионетку, созданную из Звёздного червя, для нанесения «Туманного Разреза», наносящего урон врагам в целевой области.",
    ["召唤星之虫幻化为的秘偶释放星痕技能，展开星门攻击自身前方范围内的敌人。"] = "Призывает марионетку, созданную из Звёздного червя, для применения навыка «Звёздный След»: распахивает Звёздные Врата, атакуя врагов в области перед собой.",
    ["召唤星之虫幻化为的秘偶释放星痕技能，展开星门攻击自身前方范围内的敌人。释放时若自身未拥有<HighLight>秘法能量</>，则获得<HighLight>秘法能量</>，持续70秒。若拥有<HighLight>秘法能量</>，则会额外展开一个星门并刷新<HighLight>秘法能量</>的持续时间。"] = "Призывает марионетку, созданную из Звёздного червя, для применения навыка «Звёздный След»: распахивает Звёздные Врата, атакуя врагов в области перед собой. Если при применении у вас нет <HighLight>Тайной энергии</>, вы получаете <HighLight>Тайную энергию</> на 70 сек. Если у вас уже есть <HighLight>Тайная энергия</>, открываются дополнительные Звёздные Врата, а время действия <HighLight>Тайной энергии</> обновляется.",
    ["召唤星之虫幻化为的秘偶释放烈阳颂歌，对自身12米范围内的敌方造成*d点伤害。"] = "Призывает марионетку, созданную из Звёздного червя, исполняющую «Гимн Солнца», наносящий *d ед. урона врагам в радиусе 12 метров от заклинателя.",
    ["召唤星之虫幻化为的秘偶释放烈阳颂歌，造成范围伤害。"] = "Призывает марионетку, созданную из Звёздного червя, исполняющую «Гимн Солнца» и наносящую урон по площади.",
    ["召唤星之虫幻化为的秘偶释放窥秘之眼，移除秘偶周身范围内敌方部分护盾，并造成伤害。"] = "Призывает марионетку, созданную из Звёздного червя, призывающую Око Тайноведа, которое снимает часть щитов с врагов в радиусе действия марионетки и наносит им урон.",
    ["召唤星之虫幻化为的秘偶随机释放火焰吐息或者冰霜吐息。\n火焰吐息：对路径上的敌方造成伤害并附加重伤。\n冰霜吐息：对路径上的敌方造成伤害并附加减速。"] = "Призывает марионетку в облике Звёздного червя, которая случайным образом применяет Огненное или Ледяное дыхание.\nОгненное дыхание: наносит урон врагам на пути и накладывает тяжелое ранение.\nЛедяное дыхание: наносит урон врагам на пути и накладывает замедление.",
    ["召唤星之虫幻化的秘偶来释放奇迹牌雨，对目标4.5米范围内敌方造成spellfielddisc(*id)点伤害，同时以*f**的基础概率<HyperLink stylename=\"M_Link\" u=\"6\">眩晕</>范围中心的敌方0.8秒，最多<HighLight>眩晕</>2人。"] = "Призывает марионетку, созданную из Звёздного червя, для применения «Дождя карт чудес», наносящего spellfielddisc(*id) ед. урона врагам в радиусе 4,5 м от цели и с базовой вероятностью *f** накладывающего <HyperLink stylename=\"M_Link\" u=\"6\">Оглушение</> на врагов в центре зоны на 0,8 сек. (максимум <HighLight>оглушает</> до 2 противников).",
    ["召唤星之虫幻化的秘偶来释放惩戒，对秘偶周身4米范围内的敌方造成*d点伤害。"] = "Призывает марионетку, созданную из Звёздного червя, обрушивающую «Кару», которая наносит *d ед. урона врагам в радиусе 4 метров от марионетки.",
    ["召唤星之虫幻化的秘偶来释放惩戒，对秘偶周身范围内的敌方造成伤害。"] = "Призывает марионетку, созданную из Звёздного червя, обрушивающую «Кару», которая наносит урон врагам в радиусе действия марионетки.",
    ["召唤星之虫幻化的秘偶来释放放逐，对目标5米范围内敌方造成<HighLight>5</>次*d点伤害，随后<HighLight>终结一击</>造成*d点伤害。攻击怪物时，额外附加向中心的<HyperLink stylename=\"M_Link\" u=\"2\" color=\"#f4a067\">拖拽</>效果。"] = "Призвать марионетку, трансформированную из Звездного Червя, и применить Изгнание, нанося <HighLight>5</> экземпляров *d урона врагам в радиусе 5 метров от цели, а затем <HighLight>Finish</>, который наносит *d урона. При атаке монстров применяется дополнительный эффект <HyperLink stylename=\"M_Link\" u=\"2\" color=\"#f4a067\">Pull</> по направлению к центру.",
    ["召唤星之虫幻化的秘偶来释放放逐，对目标范围内敌人持续造成伤害。对怪物额外造成聚拢效果。"] = "Призывает марионетку, созданную из Звёздного червя, применяющую «Изгнание», непрерывно наносящее урон врагам в целевой области. Монстры дополнительно стягиваются вместе.",
    ["召唤星之虫幻化的秘偶来释放日暮飓风，持续打击秘偶周身4.5米范围内敌方，每<Highlight>0.4</>秒对周身范围内敌方造成*d点伤害与1.2秒<Highlight>25%</>减速，持续<Highlight>5</>秒。"] = "Призывает марионетку, созданную из Звёздного червя, для вызова «Сумеречного Урагана», непрерывно поражающего врагов в радиусе 4,5 метров от марионетки: каждые <Highlight>0.4</> сек. наносит *d ед. урона и накладывает <Highlight>25%</> замедление на 1,2 сек. Длительность: <Highlight>5</> сек.",
    ["召唤星之虫幻化的秘偶来释放梦境分析，创建半径6米的领域，持续治疗领域范围内友方，每秒回复友方*d点生命，持续<HighLight>6</>秒。"] = "Призывает марионетку, созданную из Звёздного червя, проводящую «Анализ Сновидений»: создаёт поле радиусом 6 метров, непрерывно исцеляющее союзников внутри него и восстанавливающее по *d ед. здоровья в секунду на протяжении <HighLight>6</> сек.",
    ["召唤星之虫幻化的秘偶来释放梦境分析，创建祥和的梦境领域，持续回复领域中友方生命值。"] = "Призывает марионетку, созданную из Звёздного червя, проводящую «Анализ Сновидений»: создаёт безмятежное Поле Снов, непрерывно восстанавливающее здоровье союзников внутри него.",
    ["召唤星之虫幻化的秘偶来释放窥秘之眼，移除秘偶周身范围内敌方spellfielddisc(*id)点护盾，并造成spellfielddisc(*id)点伤害。"] = "Призывает марионетку, созданную из Звёздного червя, применяющую Око Тайноведа: снимает spellfielddisc(*id) ед. щита у врагов в радиусе действия марионетки и наносит spellfielddisc(*id) ед. урона.",
    ["召唤空想蝴蝶附身目标，buffdisc(*id)，持续6秒。"] = "Призывает Фантазийную Бабочку для вселения в цель, накладывая buffdisc(*id) на 6 сек.",
    ["召唤空想蝴蝶，持续治疗目标。"] = "Призывает Фантазийную Бабочку, непрерывно исцеляющую цель.",
    ["召唤西尔维娅灵体附身，为自身提供护盾和增益效果。使用普攻或技能时，灵体会发射子弹对目标造成伤害。"] = "Призывает дух Сильвии для одержимости, даруя себе щит и положительные эффекты. При использовании обычной атаки или умения дух выпускает пулю, нанося урон цели.",
    ["召唤西尔维娅灵体附身，持续30秒。附身期间，buffdisc(*id)，buffdisc(*id)造成bulletdisc(*id)伤害，子弹每1.8秒可触发1次，最多触发7次。"] = "Призывает дух Сильвии для одержимости на 30 сек. Во время одержимости: buffdisc(*id), buffdisc(*id) наносит урон bulletdisc(*id). Пуля может срабатывать раз в 1,8 сек., не более 7 раз.",
    ["召唤钻头保护自己，期间获得霸体和buffdisc(*id)，受到攻击时对攻击者造成1秒20%减速，持续<Highlight>4</>秒。"] = "Призывает бур для собственной защиты, получая суперброню и buffdisc(*id) на время действия. При получении удара замедляет атакующего на 20% на 1 сек. Длительность: <Highlight>4</> сек.",
    ["召唤钻头保护自己，获得霸体和护盾，并使攻击者减速。"] = "Призывает бур для собственной защиты, получая суперброню и щит, а также замедляя атакующих.",
    ["召唤铁壁骑士，使周围队友buffdisc(*id)，持续8秒。"] = "Призывает Рыцаря Железной Стены, накладывая на союзников вокруг buffdisc(*id) на 8 сек.",
    ["召唤铁壁骑士，给周围队友添加护盾。"] = "Призывает Рыцаря Железной Стены, даруя щит союзникам вокруг.",
    ["召唤魔法骑士祝福自身，buffdisc(*id)，持续10秒。"] = "Призывает рыцаря магии, который благословляет персонажа: buffdisc(*id) на 10 сек.",
    ["召唤魔法骑士，持续恢复自身生命并获得攻击和穿刺的提升效果。"] = "Призывает Магического Рыцаря, непрерывно восстанавливая собственное здоровье и получая бонусы к атаке и пронзанию.",
    ["命运湍流"] = "Бурный поток судьбы",
    ["圣光垂怜"] = "Милость Священного Света",
    ["在15米范围内的敌方单体附近召唤出空想小怪，空想小怪浮空后向目标连续释放出<HighLight>4</>个追踪子弹，每个造成bulletdisc(*id)伤害。"] = "Призывает Фантазийного миньона рядом с одиночным врагом в радиусе 15 метров. Взмыв в воздух, Фантазийный миньон выпускает в цель <HighLight>4</> самонаводящихся снаряда, каждый из которых наносит bulletdisc(*id) ед. урона.",
    ["在前方瞬间凝聚三头猩红犬影，一起发动一次咬击造成大量伤害。"] = "Мгновенно материализует перед вами тени трёх алых псов, которые совершают совместный укус, нанося огромный урон.",
    ["在敌人附近召唤出空想小怪，随后释放多个追踪子弹造成高额伤害。"] = "Призывает Фантазийного миньона рядом с врагами, который выпускает множество самонаводящихся снарядов, нанося высокий урон.",
    ["在目标位置召唤小丑，小丑出场秀会持续在身边引爆彩带炸弹，持续3秒。期间每0.5秒对范围内的目标造成spellfielddisc(*id)伤害，同时恢复伤害量50%的生命值（每次恢复不超过自身最大生命的2%）。"] = "Призывает Паяца в указанную точку. Эффектное появление Паяца в течение 3 сек. непрерывно взрывает ленточные бомбы вокруг него. Каждые 0.5 сек. пораженным целям в области наносится spellfielddisc(*id) ед. урона, восстанавливая здоровье в размере 50% от нанесенного урона (не более 2% от макс. здоровья заклинателя за раз).",
    ["在目标位置召唤小丑，持续对范围内目标造成伤害，根据伤害量回复生命。"] = "Призывает Клоуна в целевую точку: непрерывно наносит урон целям в области действия и восстанавливает здоровье в зависимости от нанесённого урона.",
    ["在目标位置召唤尤朵拉，尤朵拉召唤法阵，短暂时间后法阵爆发对目标造成*d伤害2次，然后使自身对目标造成伤害提升6%并使目标伤害降低6%，持续6秒。"] = "Призывает Юдору в целевую точку. Юдора призывает магический круг, который спустя мгновение взрывается, нанося цели *d ед. урона дважды, после чего увеличивает ваш урон по цели на 6% и снижает урон цели на 6% на 6 сек.",
    ["在目标位置召唤尤朵拉，短暂时间后对目标造成伤害，并提升后续自身对目标的伤害并使目标伤害降低。"] = "Призывает Юдору в целевую точку; спустя мгновение наносит урон цели, увеличивая ваш последующий урон по ней и снижая наносимый целью урон.",
    ["在目标位置召唤星象仪者，横踢敌人造成*d伤害，移除目标*d护盾，并有100%基础概率附加0.6秒硬直。随后直踢造成*d伤害，如果目标生命值低于25%，直踢伤害会提升至2倍。"] = "Призывает Астролябиста в целевой точке: боковой удар наносит врагам *d урона, снимает с цели *d щита и с базовым шансом 100% оглушает на 0,6 сек. Затем прямой удар наносит *d урона; если у цели менее 25% ОЗ, урон прямого удара увеличивается вдвое.",
    ["在目标位置召唤星象仪者，踢击移除目标护盾，造成伤害并附加硬直，随后二段踢击造成伤害，二段对低血量目标伤害提升。"] = "Призывает Астролябиста в целевой точке: удар снимает щит с цели, наносит урон и оглушает, затем второй удар наносит урон; по целям с малым запасом здоровья второй удар наносит повышенный урон.",
    ["在目标位置召唤梅高欧丝之影，对前方进行双重攻击。第一段攻击造成*d伤害和<Highlight>滞涩</>；第二段攻击造成*d伤害并产生<Highlight>重伤</>，被第一段击中的敌人，会受到额外的50%伤害；第二段攻击同时为周围友方单位提供一段时间内的伤害增幅。"] = "Призывает тень Мегоз в указанную область, наносящую двойной удар перед собой. Первый удар наносит *d урона и накладывает эффект <Highlight>«Замедление»</>; второй удар наносит *d урона и вызывает <Highlight>«Тяжелое ранение»</>, при этом пораженные первым ударом враги получают на 50% больше урона. Второй удар также временно увеличивает наносимый урон союзников поблизости.",
    ["在目标位置召唤梅高欧丝之影，攻击前方两次，造成滞涩和重伤。"] = "Призывает Тень Мегоуз в целевую точку: совершает два удара перед собой, вызывая тягучесть и уязвимость.",
    ["在目标位置召唤窥秘之眼链接目标，每0.5秒对目标造成*d伤害并使目标减速25%。链接最多持续4秒，目标远离窥秘之眼一定距离后链接会提前断开。"] = "Призовите Таинственное Око в выбранном месте, чтобы оно соединилось с целью, нанося урон *d каждые 0,5 сек. и замедляя цель на 25%. Связь длится до 4 сек. и прерывается раньше, если цель уходит слишком далеко от Тайного Ока.",
    ["在目标位置召唤窥秘之眼，对目标造成持续伤害和减速。"] = "Призвать Тайные глаза, любопытствующие в выбранном месте, чтобы наносить непрерывный урон и замедлять цель.",
    ["在目标位置召唤重斧骑士使用劈击，对范围内敌人造成spellfielddisc(*id)伤害，并对中心区域的敌人100%概率造成<Highlight>眩晕</>。"] = "Призывает Рыцаря с тяжелым топором в целевой точке: он рубящим ударом наносит врагам в области spellfielddisc(*id) урона и с шансом 100% <Highlight>оглушает</> врагов в центре.",
    ["在目标位置召唤重斧骑士使用劈击，对范围内敌人造成spellfielddisc(*id)伤害，并对中心区域的敌人以70%的基础概率造成1秒<Highlight>眩晕</>。"] = "Призывает в указанную точку рыцаря с тяжёлым топором, который совершает рубящий удар: наносит врагам в области spellfielddisc(*id) ед. урона и с базовой вероятностью 70% накладывает на врагов в эпицентре <Highlight>оглушение</> на 1 сек.",
    ["在目标位置召唤重斧骑士，对范围内敌人造成伤害，对中心的敌人造成眩晕。"] = "Призывает Рыцаря с тяжёлым топором в целевую точку: наносит урон врагам в области действия и оглушает врагов в центре.",
    ["在目标区域召唤出巨龟原地旋转并向周围溅射浪花，对敌方造成伤害并使敌方陷入负面效果。"] = "Призывает Исполинскую Черепаху в целевую область, которая вращается на месте и разбрызгивает волны, нанося урон врагам и накладывая на них негативные эффекты.",
    ["在目标区域召唤出巨龟原地旋转并向周围溅射浪花，造成三次*d点伤害，随后震地造成*d点伤害。被浪花溅射到的敌人会被持续施加2秒虚弱、滞涩效果。"] = "Призывает в указанную область исполинскую черепаху, которая вращается на месте и разбрызгивает волны, нанося урон *d ед. трижды, после чего сотрясает землю с нанесением *d ед. урона. Враги, задетые брызгами, непрерывно подвергаются эффектам слабости и скованности на 2 сек.",
    ["在自身前方扇形区域内瞬间凝聚三头猩红犬影，一起发动一次咬击，造成*d点伤害。"] = "Мгновенно материализует тени трёх алых псов в секторной области перед собой, совершая совместный укус с нанесением *d ед. урона.",
    ["在自身面前召唤一个狒狒，狒狒每间隔一段时间会给小队所有成员添加一个随机增益。\n随机增益：攻击增加、技能增强增加、怪物专攻增加。"] = "Призовите перед собой бабуина, и бабуин время от времени будет добавлять случайный бафф всем членам команды. \n Случайные преимущества: усиление атаки, усиление улучшения навыков, повышение специализации против монстров.",
    ["在自身面前召唤一只狒狒，持续21秒。召唤时及之后每<Highlight>6</>秒，狒狒会为30米范围内的队友添加一个随机增益。\n随机增益：buffdisc(*id)，持续<Highlight>6</>秒；buffdisc(*id)，持续<Highlight>6</>秒；buffdisc(*id)，持续<Highlight>6</>秒；\n该技能有小队冷却时间<Highlight>30</>秒。"] = "Призывает павиана перед вами на 21 секунду. При вызове и каждые <Highlight>6</> секунд после этого Бабуин добавляет случайный положительный эффект товарищам по команде в радиусе 30 метров. \nСлучайные усиления: buffdisc(*id), длится <Highlight>6</> секунд; buffdisc(*id), длится <Highlight>6</> секунд; buffdisc(*id), длится <Highlight>6</> секунд; \nКомандное время охлаждения этого навыка составляет <Highlight>30</> секунд.",
    ["在身前位置召唤兔子玩偶用头震地，对前方扇形范围内敌人造成*d伤害，并有50%的基础概率击倒敌人。同时附带余波，对周围敌人造成*d伤害。"] = "Призовите куклу-кролика перед собой, чтобы она ударила ее головой об землю, нанеся *d урон врагам в веерообразной области впереди с базовым шансом 50% сбить их с ног. Он также вызывает толчок, нанося *d урон окружающим врагам.",
    ["在身前位置召唤兔子玩偶用头震地，有概率击倒前方扇形范围内敌人，同时附带余波。"] = "Призовите куклу-кролика перед собой, чтобы она ударила его головой о землю, с шансом сбить с ног врагов в веерообразной области впереди, а также вызвать афтершок.",
